func TestCopyMaybeTextAndSetMaybeKind(t *testing.T) {
	item := aastypes.NewItem("a", []string{})
	item.SetMaybeText(aascommon.NewAndPointTo("old"))
	other := aastypes.NewItem("b", []string{})
	aasverification.CopyMaybeTextAndSetMaybeKind(item, other)
	if item.MaybeText() != nil {
		t.Fatalf("Expected no maybe-text, but got: %v", *item.MaybeText())
	}
	if item.MaybeKind() == nil || *item.MaybeKind() != aastypes.KindAlpha {
		t.Fatalf("Expected the maybe-kind Alpha, but got: %v", item.MaybeKind())
	}
}

